			)

			for _, c := range cpuValues {
				goodValues = append(goodValues, strconv.Itoa(c))
				if c == p.config.CPU {
					valid = true
					break
				}
			}

			if !valid {
				return nil, fmt.Errorf("Invalid cpu value: %d (valid values: %s)",
					p.config.Memory, strings.Join(goodValues, ", "))
			}

			cpuShares = p.config.CPU
		}
