+func NewHandler(urlStr, prefix, applicationName string) (http.Handler, error) {
 	mux := http.NewServeMux()

 	etags := make(map[string]string)
	var mx sync.Mutex
	calcTag := func(name string, data []byte) string {
		mx.Lock()
		defer mx.Unlock()
		tag, ok := etags[name]
		if ok {
			return tag
		}
		sum := sha256.Sum256(data)
		tag = `W/"` + hex.EncodeToString(sum[:]) + `"`
		etags[name] = tag
		return tag
	}

