	case 1:
		return id.Ed25519.Verify(msg, sig)
	case 2:
		return id.X509EC.Verify(msg, sig)
	case 3:
		return id.Proxy.Verify(msg, sig)
	default:
		return errors.New("unknown identity")
	}
}

