				require.NoError(t, err)
				require.NotEmpty(t, certChain)
				svid := certChain[0]

				entryID := spiffeid.Must(entry.SpiffeId.TrustDomain, entry.SpiffeId.Path)
				require.Equal(t, []*url.URL{entryID.URL()}, svid.URIs)

				// Use entry ttl when defined
