func LimitCheckAny(ctx context.Context, checks ...Checker) error {
	if !All(ctx) {
		return newGeneric(true, "")
	}

	// ensure we don't get hammered with auth checks (or DB calls, for example)
	err := checkLimit(ctx)
	if err != nil {
		return err
	}

	if len(checks) == 0 {
		return nil
	}
	for _, c := range checks {
		if c != nil && c(ctx) {
			addAuthAttrs(ctx)
			return nil
		}
	}

	return newGeneric(false, "")
}

