func generateName(base string, o interface{}) string {
	hasher := fnv.New32a()
	hashutil.DeepHashObject(hasher, o)
	hash := utilrand.SafeEncodeString(fmt.Sprint(hasher.Sum32()))
	if len(base)+len(hash) > maxNameLength {
