	// ListenIP() + ":4040" rather than just ":4040".

	var err error
	i.listener, err = net.Listen("tcp", addr)
	if err != nil {
		return err
	}
	i.addr = i.listener.Addr().String() // in case it changed

	if err := i.ch.Serve(i.listener); err != nil {
		return err
	}

	return nil
}

