+		// gRPC port for Waypoint installations.
+		if idx := strings.IndexByte(u.Host, ':'); idx < 0 {
+			c.Server.Address += ":9701"
+		}
 	}

 	// Specifically http will override TLS
	if u.Scheme == "http" {
		c.Server.Tls = false
